import random
import struct
from typing import List

# Target: generate bytes for FUZZ_PARAM_STR used as Mixbox LUT data.
# The fuzzer stub picks a size 0..min(1024, len(lut)) and passes the first
# 'size' bytes to initializeMixbox. Therefore, providing a buffer up to 1024
# bytes with diverse, valid content is ideal. Contents are arbitrary binary.

_MAX_TOTAL = 4096
_MAX_LUT = 1024

_DEF_SEEDS = [
    # Short canonical patterns
    b"",  # allow size=0 case
    bytes(range(256)),  # 0..255 ramp
    (b"\x00\xff" * 512)[:1024],  # alternating extremes
    b"MIXBOX-LUT\x00" + b"\x00" * 100,  # small tagged header-ish
]


def _rand_bytes(r: random.Random, n: int) -> bytes:
    # Mix biased distributions to create interesting patterns
    out = bytearray(n)
    modes = [
        "uniform", "low", "high", "ramp_up", "ramp_down", "blocks",
        "repeated", "gaussian"
    ]
    mode = r.choice(modes)
    if mode == "uniform":
        for i in range(n):
            out[i] = r.randrange(256)
    elif mode == "low":
        for i in range(n):
            out[i] = r.randrange(0, 32)
    elif mode == "high":
        for i in range(n):
            out[i] = r.randrange(224, 256)
    elif mode == "ramp_up":
        for i in range(n):
            out[i] = (i * 7) & 0xFF
    elif mode == "ramp_down":
        for i in range(n):
            out[i] = ((n - 1 - i) * 9) & 0xFF
    elif mode == "blocks":
        i = 0
        while i < n:
            b = r.randrange(256)
            ln = r.randrange(1, min(64, n - i) + 1)
            out[i:i+ln] = bytes([b]) * ln
            i += ln
    elif mode == "repeated":
        base = _rand_bytes(r, r.randrange(1, 33))
        rep = (n + len(base) - 1) // len(base)
        out[:] = (base * rep)[:n]
    elif mode == "gaussian":
        # Centered around mid gray with variance
        for i in range(n):
            v = int(r.gauss(127, 40))
            out[i] = max(0, min(255, v))
    return bytes(out)


def _maybe_pack_header(r: random.Random) -> bytes:
    # Add a tiny pseudo header that could trigger different code paths
    # even if consumer treats bytes opaquely.
    # Layout: magic(8) | version(u16) | flags(u16) | len(u32)
    magic_options = [b"MIXBOX\x00", b"LUTDATA\x00", b"MBX!\x00\x00\x00\x00"]
    magic = r.choice(magic_options)
    version = r.randrange(0, 5)
    flags = 0
    # Mix flags bits
    for bit in range(r.randrange(0, 8)):
        flags |= 1 << r.randrange(0, 16)
    payload_len = r.randrange(0, _MAX_LUT)
    return magic + struct.pack("<HHI", version, flags & 0xFFFF, payload_len)


def _compose_lut(r: random.Random) -> bytes:
    # Choose a strategy to compose up to 1024 bytes
    strategies = ["pure_rand", "header_then_rand", "segments", "predef", "palette"]
    strat = r.choice(strategies)

    if strat == "predef":
        buf = bytearray(r.choice(_DEF_SEEDS))
        # Maybe extend to vary size
        if len(buf) < _MAX_LUT and r.random() < 0.6:
            extra = _rand_bytes(r, r.randrange(1, _MAX_LUT - len(buf) + 1))
            buf.extend(extra)
        return bytes(buf[:_MAX_LUT])

    if strat == "pure_rand":
        n = r.randrange(0, _MAX_LUT + 1)
        return _rand_bytes(r, n)

    if strat == "header_then_rand":
        header = _maybe_pack_header(r)
        remaining = max(0, _MAX_LUT - len(header))
        tail = _rand_bytes(r, r.randrange(0, remaining + 1))
        return (header + tail)[:_MAX_LUT]

    if strat == "segments":
        buf = bytearray()
        while len(buf) < _MAX_LUT and r.random() < 0.92:
            seg_type = r.choice(["rand", "zeros", "ff", "ramp", "repeat"]) 
            max_add = _MAX_LUT - len(buf)
            seg_len = r.randrange(1, min(128, max_add) + 1)
            if seg_type == "rand":
                seg = _rand_bytes(r, seg_len)
            elif seg_type == "zeros":
                seg = b"\x00" * seg_len
            elif seg_type == "ff":
                seg = b"\xff" * seg_len
            elif seg_type == "ramp":
                seg = bytes(((i * r.randrange(1, 13)) & 0xFF) for i in range(seg_len))
            else:  # repeat
                base = _rand_bytes(r, r.randrange(1, min(16, seg_len) + 1))
                seg = (base * ((seg_len + len(base) - 1)//len(base)))[:seg_len]
            buf.extend(seg)
        return bytes(buf[:_MAX_LUT])

    if strat == "palette":
        # Build from a small palette of values (could mimic quantized LUTs)
        pal_size = r.randrange(2, 17)
        palette = [r.randrange(256) for _ in range(pal_size)]
        n = r.randrange(0, _MAX_LUT + 1)
        return bytes(palette[r.randrange(pal_size)] for _ in range(n))

    return b""  # fallback


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    buf = _compose_lut(r)
    # Ensure total size constraint (already <= 1024) and return
    return buf[:min(len(buf), _MAX_TOTAL)]
